const categoryById=id=>categories.find(category=>category.id===id);
const categoryByTitle=title=>categories.find(category=>category.title===title);
const categoryId=value=>categoryById(value)?.id||categoryByTitle(value)?.id||'home';
const categoryLabel=(value,fallback='Разное')=>categoryById(value)?.title||categoryByTitle(value)?.title||fallback;

