const saved=JSON.parse(localStorage.getItem('pomogay_preferences')||'{}');
const state={page:'home',session:null,cloudReady:false,services:[...seedServices],tasks:[],conversations:[],messages:[],people:[],activeConversation:null,chatSearch:'',query:'',catalogMode:'helpers',category:'all',subcategory:'all',verifiedOnly:false,view:'list',radius:Number(saved.radius||25),locationName:saved.locationName||'Москва',coords:saved.coords||{lat:55.7558,lng:37.6176},homeIntent:null,createMode:'task',selectedAddress:null,favorites:[],user:{name:'',city:'Москва',verified:false},maps:new Map(),realtimeChannel:null};
const todayIso=new Date().toISOString().slice(0,10);

function savePreferences(){localStorage.setItem('pomogay_preferences',JSON.stringify({radius:state.radius,locationName:state.locationName,coords:state.coords}))}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function arg(value){return JSON.stringify(value).replace(/</g,'\\u003c')}
function initials(name='Пользователь'){const parts=String(name).trim().split(/\s+/).filter(Boolean);return(parts[0]?.[0]||'П')+(parts.length>1?(parts.at(-1)?.[0]||''):'')}
function formatMoney(value){return value==null?'По договорённости':`от ${Number(value).toLocaleString('ru-RU')} ₽`}
function numberFromText(value){const n=String(value||'').replace(/[^0-9.,]/g,'').replace(',','.');return n?Number(n):null}
function formatDate(value){return value?new Intl.DateTimeFormat('ru-RU',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Время по договорённости'}
function toast(message){toastEl.textContent=message;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),3200)}
function userName(){return state.user.name||state.session?.user?.user_metadata?.name||state.session?.user?.email?.split('@')[0]||'Пользователь'}
function portrait(avatarUrl,name,index=null,size='medium'){
  if(avatarUrl)return `<span class="avatar avatar-${size}" style="background-image:url('${escapeHtml(avatarUrl)}')" aria-hidden="true"></span>`;
  if(Number.isInteger(index))return `<span class="avatar avatar-${size} portrait portrait-${index}" aria-hidden="true"></span>`;
  return `<span class="avatar avatar-${size} avatar-initials" aria-hidden="true">${escapeHtml(initials(name))}</span>`;
}

const navItems=[['home','⌂','Главная'],['catalog','⌕','Поиск'],['create','+','Создать'],['chats','<svg class="nav-chat-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h14a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H10l-5 4v-4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z"/></svg>','Чаты'],['profile','<svg class="nav-profile-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7 8a7 7 0 0 0-14 0"/></svg>','Профиль']];
function shell(content,options={}){
  app.innerHTML=`<div class="app-shell"><header class="topbar"><button class="brand" onclick="go('home')" aria-label="На главную"><span class="brand-mark">П</span><span>Помогай</span></button></header><main class="main ${options.wide?'main-wide':''}">${content}</main><nav class="bottom-nav" aria-label="Основная навигация">${navItems.map(([id,icon,label])=>`<button class="${state.page===id?'active':''} ${id==='create'?'create-nav':''}" onclick="go('${id}')"><span>${icon}</span><small>${label}</small></button>`).join('')}</nav></div>`;
  requestAnimationFrame(afterRender);
}
function go(page){state.page=page;state.activeConversation=null;window.scrollTo({top:0,behavior:'smooth'});render()}

function home(){
  shell(`<section class="home-hero"><div class="intro-copy"><h1>Люди помогают людям</h1><p>Найдите подходящего специалиста или расскажите, чем помочь. Вы выбираете человека, место и удобное время.</p></div></section><section class="intent-grid home-intents"><button class="intent-card find ${state.homeIntent==='find'?'selected':''}" onclick="selectIntent('find')"><span class="intent-icon"><svg class="helping-hand-icon" viewBox="0 0 48 48" aria-hidden="true"><path d="M18 24V9a3.5 3.5 0 0 1 7 0v11-7a3.5 3.5 0 0 1 7 0v9-5a3.5 3.5 0 0 1 7 0v10c0 9-5.5 15-14 15h-2c-5.5 0-9-2.5-12-7l-4-6a3.7 3.7 0 0 1 6-4.3l5 5.3Z"/></svg></span><span><b>Найти помощь</b><small>Выбрать подходящего специалиста</small></span><i>›</i></button><button class="intent-card offer ${state.homeIntent==='need'?'selected':''}" onclick="selectIntent('need')"><span class="intent-icon">+</span><span><b>Нужна помощь</b><small>Выбрать задачу и место</small></span><i>›</i></button></section>${state.homeIntent?homeMapPanel():''}<section class="section-block"><div class="section-heading"><div><h2>Популярные категории</h2><p>Направления с конкретными специализациями</p></div><button class="text-button" onclick="showAllCategories()">Все категории</button></div><div class="category-grid">${categories.slice(0,12).map(categoryCard).join('')}</div></section><section class="section-block specialists-section"><div class="section-heading"><div><h2>Специалисты рядом</h2><p>Выбирайте по опыту, рейтингу и реальным отзывам</p></div><button class="text-button" onclick="go('catalog')">Смотреть всех</button></div><div class="specialist-grid">${filteredServices().slice(0,4).map(serviceCard).join('')}</div></section>`,{wide:true});
}
function homeMapPanel(){
  return `<section class="home-map-panel" id="homeIntentPanel"><div class="map-panel-head"><div><span class="status-pill">${state.homeIntent==='find'?'Ищу помощника':'Хочу разместить задачу'}</span><h2>Где нужна помощь?</h2></div><button class="secondary-button" onclick="useMyLocation('homeMap')">⌖ Использовать моё местоположение</button></div><div class="map-layout"><div id="homeMap" class="map-canvas" aria-label="Карта поиска"></div><div class="map-controls"><label class="range-field"><span>Расстояние <b id="homeRadiusValue">${state.radius} км</b></span><input type="range" min="1" max="500" value="${state.radius}" oninput="previewRadius(this,'homeRadiusValue')" onchange="commitRadius(this.value)"></label><div class="quick-options"><b>${state.homeIntent==='find'?'Что ищем':'Чем помочь?'}</b>${categories.slice(0,6).map(c=>`<button onclick="applyCategory('${c.id}')">${escapeHtml(c.title)}</button>`).join('')}<button onclick="showAllCategories()">Другие категории</button></div><button class="primary-button full" onclick="continueIntent()">${state.homeIntent==='find'?'Показать варианты':'Продолжить к задаче'}</button></div></div></section>`;
}
function categoryCard(category){return `<button class="category-card category-${category.id}" onclick="openCategory('${category.id}')"><span class="category-mark">${category.mark}</span><span><b>${escapeHtml(category.title)}</b><small>${escapeHtml(category.description)}</small></span><i>›</i></button>`}
function selectIntent(intent){state.homeIntent=intent;render();setTimeout(()=>document.querySelector('#homeIntentPanel')?.scrollIntoView({behavior:'smooth',block:'start'}),80)}
function continueIntent(){if(state.homeIntent==='find'){state.catalogMode='helpers';state.view='map';go('catalog')}else{state.createMode='task';go('create')}}
function applyCategory(id){state.category=id;state.subcategory='all';continueIntent()}
function openCategory(id){const category=categoryById(id);if(!category)return;modal(`<div class="modal-heading"><span class="category-mark">${category.mark}</span><div><h2>${escapeHtml(category.title)}</h2><p>${escapeHtml(category.description)}</p></div></div><div class="subcategory-list">${category.subs.map(sub=>`<button onclick="chooseSubcategory('${id}',${arg(sub)})"><span>${escapeHtml(sub)}</span><i>›</i></button>`).join('')}</div>`)}
function showAllCategories(){modal(`<h2>Все категории</h2><p class="muted">Выберите основное направление.</p><div class="modal-category-grid">${categories.map(categoryCard).join('')}</div>`)}
function chooseSubcategory(id,sub){state.category=id;state.subcategory=sub;closeModal();if(state.homeIntent==='need'){state.createMode='task';go('create')}else{state.catalogMode='helpers';go('catalog')}}

function distanceFor(row){
  if(Number.isFinite(row.distance))return row.distance;
  if(!Number.isFinite(row.latitude)||!Number.isFinite(row.longitude))return null;
  const a=state.coords,r=6371,dLat=(row.latitude-a.lat)*Math.PI/180,dLon=(row.longitude-a.lng)*Math.PI/180,q=Math.sin(dLat/2)**2+Math.cos(a.lat*Math.PI/180)*Math.cos(row.latitude*Math.PI/180)*Math.sin(dLon/2)**2;
  return Math.round(2*r*Math.asin(Math.sqrt(q))*10)/10;
}
function normalizedService(row,index=0){
  const category=categoryId(row.category);
  return {id:row.id,owner_id:row.owner_id||null,title:row.title,category,subcategory:row.subcategory||categoryById(category)?.subs?.[0]||'',name:row.profiles?.name||row.name||'Помощник',rating:Number(row.profiles?.rating||row.rating||5),reviews:Number(row.reviews||0),price_from:row.price_from,city:row.city||'Москва',verified:!!(row.profiles?.verified??row.verified),demo:String(row.id||'').startsWith('demo-'),distance:distanceFor(row),response_minutes:row.response_minutes||60,description:row.description||'',avatar_url:row.profiles?.avatar_url||row.avatar_url||null,portrait:Number.isInteger(row.portrait)?row.portrait:index%4,latitude:row.latitude,longitude:row.longitude};
}
function filteredServices(){const q=state.query.trim().toLowerCase();return state.services.map(normalizedService).filter(item=>(state.category==='all'||item.category===state.category)&&(state.subcategory==='all'||item.subcategory===state.subcategory)&&(!state.verifiedOnly||item.verified)&&(item.distance==null||item.distance<=state.radius)&&(!q||`${item.title} ${item.name} ${item.subcategory}`.toLowerCase().includes(q)))}
function filteredTasks(){const q=state.query.trim().toLowerCase();return state.tasks.filter(item=>(state.category==='all'||item.category===state.category)&&(state.subcategory==='all'||item.subcategory===state.subcategory)&&(!q||`${item.title} ${item.description||''} ${item.subcategory||''}`.toLowerCase().includes(q)))}
function serviceCard(service,index=0){
  const s=normalizedService(service,index);
  return `<article class="specialist-card"><button class="card-main" onclick="openService(${arg(s.id)})"><div class="specialist-photo">${portrait(s.avatar_url,s.name,s.portrait,'card')}<span class="online-dot" aria-label="Доступен"></span></div><div class="specialist-body"><div class="card-kicker">${escapeHtml(categoryLabel(s.category))} · ${escapeHtml(s.subcategory)}</div><h3>${escapeHtml(s.title)}</h3><div class="person-row"><b>${escapeHtml(s.name)}</b>${s.demo?'<span class="status-pill">Пример</span>':s.verified?'<span class="verified-chip">Проверен</span>':''}</div><div class="card-meta"><span>★ ${s.rating.toFixed(1)}${s.reviews?` (${s.reviews})`:''}</span><span>${s.distance==null?escapeHtml(s.city):`${s.distance} км`}</span></div><div class="card-price">${formatMoney(s.price_from)}</div></div></button><button class="favorite-button ${state.favorites.includes(s.id)?'active':''}" onclick="toggleFavorite(${arg(s.id)})" aria-label="Добавить в избранное">♡</button></article>`;
}
function taskCard(task){return `<article class="task-card"><div class="task-card-head"><span class="status-pill">Задача пользователя</span><span>${formatDate(task.scheduled_at)}</span></div><h3>${escapeHtml(task.title)}</h3><p>${escapeHtml(task.description||'')}</p><div class="task-tags"><span>${escapeHtml(categoryLabel(task.category))}</span>${task.subcategory?`<span>${escapeHtml(task.subcategory)}</span>`:''}<span>${escapeHtml(task.address||'Адрес после отклика')}</span></div><div class="task-bottom"><b>${task.budget==null?'Бюджет по договорённости':`${Number(task.budget).toLocaleString('ru-RU')} ₽`}</b><button class="secondary-button" onclick="respondToTask(${arg(task.id)})">Откликнуться</button></div></article>`}

function catalog(){
  const items=state.catalogMode==='helpers'?filteredServices():filteredTasks();
  shell(`<section class="catalog-head"><div><span class="eyebrow">Поиск рядом</span><h1>${state.catalogMode==='helpers'?'Специалисты':'Задачи пользователей'}</h1></div><div class="segmented"><button class="${state.catalogMode==='helpers'?'active':''}" onclick="setCatalogMode('helpers')">Специалисты</button><button class="${state.catalogMode==='tasks'?'active':''}" onclick="setCatalogMode('tasks')">Задачи</button></div></section><form class="search-row" onsubmit="searchCatalog(event)"><input name="query" value="${escapeHtml(state.query)}" placeholder="Специалист, услуга или ФИО"><button class="primary-button">Найти</button><button type="button" class="icon-button" onclick="showFilters()" aria-label="Открыть фильтры">≡</button></form><section class="catalog-tools"><div class="category-scroll"><button class="filter-chip ${state.category==='all'?'active':''}" onclick="setCategory('all')">Все</button>${categories.map(c=>`<button class="filter-chip ${state.category===c.id?'active':''}" onclick="setCategory('${c.id}')">${escapeHtml(c.title)}</button>`).join('')}</div><div class="view-switch"><button class="${state.view==='list'?'active':''}" onclick="setView('list')">Список</button><button class="${state.view==='map'?'active':''}" onclick="setView('map')">Карта</button></div></section>${activeSubcategoryBar()}${state.view==='map'?catalogMap(items):catalogList(items)}`,{wide:true});
}
function activeSubcategoryBar(){const category=categoryById(state.category);if(!category)return'';return `<div class="subcategory-scroll"><button class="${state.subcategory==='all'?'active':''}" onclick="setSubcategory('all')">Все направления</button>${category.subs.map(sub=>`<button class="${state.subcategory===sub?'active':''}" onclick="setSubcategory(${arg(sub)})">${escapeHtml(sub)}</button>`).join('')}</div>`}
function catalogList(items){if(!items.length)return emptyState(state.catalogMode==='tasks'?'Пока нет открытых задач по этим условиям':'Ничего не найдено','Измените категорию, расстояние или поисковый запрос.');return state.catalogMode==='helpers'?`<div class="specialist-grid catalog-grid">${items.map(serviceCard).join('')}</div>`:`<div class="task-list">${items.map(taskCard).join('')}</div>`}
function catalogMap(items){
  let results=emptyState('На карте пока пусто','Измените фильтры или расстояние.');
  if(items.length)results=state.catalogMode==='helpers'?items.slice(0,6).map(serviceCard).join(''):items.slice(0,6).map(taskCard).join('');
  return `<section class="catalog-map-layout"><div class="map-column"><div class="map-toolbar"><button class="secondary-button" onclick="useMyLocation('catalogMap')">⌖ Использовать моё местоположение</button><span>${items.length} вариантов</span></div><div id="catalogMap" class="map-canvas map-large"></div><label class="range-field map-radius"><span>Расстояние <b id="catalogRadiusValue">${state.radius} км</b></span><input type="range" min="1" max="500" value="${state.radius}" oninput="previewRadius(this,'catalogRadiusValue')" onchange="commitRadius(this.value)"></label></div><aside class="map-results">${results}</aside></section>`;
}
function emptyState(title,text){return `<div class="empty-state"><span>○</span><h3>${escapeHtml(title)}</h3><p>${escapeHtml(text)}</p></div>`}
function searchCatalog(event){event.preventDefault();state.query=String(new FormData(event.currentTarget).get('query')||'').trim();render()}
function setCatalogMode(mode){state.catalogMode=mode;render()}
function setCategory(id){state.category=id;state.subcategory='all';render()}
function setSubcategory(value){state.subcategory=value;render()}
function setView(view){state.view=view;render()}
function previewRadius(input,labelId){state.radius=Number(input.value);document.querySelector(`#${labelId}`).textContent=`${input.value} км`;updateMapRadius()}
function commitRadius(value){state.radius=Number(value);savePreferences();render()}
function subcategoryOptions(category,selected,includeAll=false){const item=categoryById(category);return `${includeAll?'<option value="all">Все направления</option>':''}${(item?.subs||[]).map(sub=>`<option value="${escapeHtml(sub)}" ${selected===sub?'selected':''}>${escapeHtml(sub)}</option>`).join('')}`}
function showFilters(){modal(`<h2>Фильтры поиска</h2><div class="form-grid"><label class="field"><span>Основная категория</span><select id="filterCategory" onchange="refreshFilterSubcategories(this.value)"><option value="all">Все категории</option>${categories.map(c=>`<option value="${c.id}" ${state.category===c.id?'selected':''}>${escapeHtml(c.title)}</option>`).join('')}</select></label><label class="field"><span>Направление</span><select id="filterSubcategory">${subcategoryOptions(state.category,state.subcategory,true)}</select></label><label class="range-field full-field"><span>Расстояние <b id="modalRadiusValue">${state.radius} км</b></span><input id="filterRadius" type="range" min="1" max="500" value="${state.radius}" oninput="document.querySelector('#modalRadiusValue').textContent=this.value+' км'"></label><label class="check-row"><input id="filterVerified" type="checkbox" ${state.verifiedOnly?'checked':''}><span><b>Только с подтверждённой личностью</b><small>Показывать пользователей, прошедших проверку</small></span></label><button class="primary-button full-field" onclick="applyFilters()">Применить</button></div>`)}
function refreshFilterSubcategories(category){document.querySelector('#filterSubcategory').innerHTML=subcategoryOptions(category,'all',true)}
function applyFilters(){state.category=document.querySelector('#filterCategory').value;state.subcategory=document.querySelector('#filterSubcategory').value;state.radius=Number(document.querySelector('#filterRadius').value);state.verifiedOnly=document.querySelector('#filterVerified').checked;savePreferences();closeModal();render()}

function create(){
  if(!state.session){shell(`<section class="auth-gate"><h1>Войдите, чтобы публиковать</h1><p>Задачи и предложения помощи связаны с профилем реального пользователя.</p><div class="button-row"><button class="primary-button" onclick="showAuth('signup')">Создать аккаунт</button><button class="secondary-button" onclick="showAuth('login')">Войти</button></div></section>`);return}
  const category=state.category==='all'?'home':state.category;
  shell(`<section class="create-head"><h1>${state.createMode==='task'?'Попросить о помощи':'Хочу помогать'}</h1><div class="segmented create-tabs"><button class="${state.createMode==='task'?'active':''}" onclick="setCreateMode('task')">Нужна помощь</button><button class="${state.createMode==='service'?'active':''}" onclick="setCreateMode('service')">Хочу помогать</button></div></section><form class="publish-form" onsubmit="${state.createMode==='task'?'publishTask(event)':'publishService(event)'}"><section class="form-section"><div class="form-section-title"><span>1</span><div><h2>${state.createMode==='task'?'Чем помочь?':'Как помогаю'}</h2><p>Коротко и конкретно опишите результат.</p></div></div><label class="field"><span>${state.createMode==='task'?'Название задачи':'Как помогаю'}</span><input name="title" required minlength="3" maxlength="120" placeholder="${state.createMode==='task'?'Например, выгулять собаку вечером':'Например, консультирую по семейному праву'}"></label><label class="field"><span>Подробности</span><textarea name="description" required minlength="10" maxlength="4000" rows="5" placeholder="Добавьте важные детали, объём работы и ожидания"></textarea></label></section><section class="form-section"><div class="form-section-title"><span>2</span><div><h2>Категория</h2><p>Выберите направление и специализацию.</p></div></div><div class="two-fields"><label class="field"><span>Основная категория</span><select name="category" onchange="updateCreateSubcategories(this.value)" required>${categories.map(c=>`<option value="${c.id}" ${category===c.id?'selected':''}>${escapeHtml(c.title)}</option>`).join('')}</select></label><label class="field"><span>Направление</span><select id="createSubcategory" name="subcategory" required>${subcategoryOptions(category,state.subcategory==='all'?'':state.subcategory)}</select></label></div></section>${state.createMode==='task'?taskFields():serviceFields()}<div id="publishError" class="form-error" hidden></div><button class="primary-button publish-button">${state.createMode==='task'?'Опубликовать задачу':'Опубликовать помощь'}</button></form>`);
}
function taskFields(){
  const today=new Date();today.setMinutes(today.getMinutes()-today.getTimezoneOffset());
  return `<section class="form-section"><div class="form-section-title"><span>3</span><div><h2>Место и время</h2><p>Точка на карте видна только в пределах, необходимых для поиска.</p></div></div><label class="field"><span>Адрес или район</span><div class="input-action"><input id="addressInput" name="address" required maxlength="200" value="${escapeHtml(state.selectedAddress?.address||'')}" placeholder="Улица, район или ориентир"><button type="button" onclick="openAddressPicker()">Выбрать на карте</button></div></label><input type="hidden" name="latitude" value="${state.selectedAddress?.lat||''}"><input type="hidden" name="longitude" value="${state.selectedAddress?.lng||''}"><div class="two-fields"><label class="field"><span>Дата</span><input name="date" type="date" min="${today.toISOString().slice(0,10)}" required></label><label class="field"><span>Время</span><input name="time" type="time" required></label></div><label class="field"><span>Бюджет, ₽</span><input name="budget" inputmode="decimal" placeholder="Можно оставить пустым"></label></section>`;
}
function serviceFields(){return `<section class="form-section"><div class="form-section-title"><span>3</span><div><h2>Условия</h2><p>Укажите стартовую цену и формат помощи.</p></div></div><div class="two-fields"><label class="field"><span>Цена от, ₽</span><input name="price" inputmode="decimal" required placeholder="1500"></label><label class="field"><span>Формат</span><select name="format"><option>С выездом</option><option>Онлайн</option><option>У меня</option><option>По договорённости</option></select></label></div></section>`}
function setCreateMode(mode){state.createMode=mode;render()}
function updateCreateSubcategories(category){document.querySelector('#createSubcategory').innerHTML=subcategoryOptions(category,'')}
function openAddressPicker(){modal(`<h2>Выберите место на карте</h2><p class="muted">Нажмите на карту или определите текущее местоположение.</p><div id="addressMap" class="map-canvas modal-map"></div><div class="button-row modal-actions"><button class="secondary-button" onclick="useMyLocation('addressMap',true)">⌖ Моё местоположение</button><button class="primary-button" onclick="confirmAddress()">Выбрать точку</button></div>`);requestAnimationFrame(()=>initMap('addressMap',[],true))}
function confirmAddress(){const map=state.maps.get('addressMap'),center=map?.__selected||map?.getCenter?.()||{lat:state.coords.lat,lng:state.coords.lng};state.selectedAddress={address:`${state.locationName}, выбранная точка`,lat:Number(center.lat.toFixed(6)),lng:Number(center.lng.toFixed(6))};closeModal();render();toast('Место добавлено к публикации')}
function setFormBusy(form,busy){const button=form.querySelector('button[type="submit"],.publish-button');if(button){button.disabled=busy;button.dataset.label||=button.textContent;button.textContent=busy?'Сохраняем…':button.dataset.label}}
function showFormError(form,message){const box=form.querySelector('.form-error');if(box){box.hidden=false;box.textContent=message}else toast(message)}

async function publishTask(event){
  event.preventDefault();if(!requireAuth())return;const form=event.currentTarget,d=Object.fromEntries(new FormData(form));setFormBusy(form,true);
  try{
    const scheduledAt=new Date(`${d.date}T${d.time}`);if(Number.isNaN(scheduledAt.getTime()))throw new Error('Выберите дату и время.');
    const row={customer_id:state.session.user.id,title:String(d.title).trim(),category:d.category,subcategory:d.subcategory,description:String(d.description).trim(),budget:numberFromText(d.budget),address:String(d.address).trim(),latitude:d.latitude?Number(d.latitude):null,longitude:d.longitude?Number(d.longitude):null,scheduled_at:scheduledAt.toISOString(),status:'open'};
    let result=await sb.from('tasks').insert(row).select().single();
    if(result.error&&String(result.error.message).includes('subcategory')){delete row.subcategory;result=await sb.from('tasks').insert(row).select().single()}
    if(result.error)throw result.error;state.selectedAddress=null;await loadCloud();state.catalogMode='tasks';state.page='catalog';render();toast('Задача опубликована');
  }catch(error){showFormError(form,friendlyDatabaseError(error,'Не удалось опубликовать задачу.'))}finally{setFormBusy(form,false)}
}
async function publishService(event){
  event.preventDefault();if(!requireAuth())return;const form=event.currentTarget,d=Object.fromEntries(new FormData(form));setFormBusy(form,true);
  try{
    const row={owner_id:state.session.user.id,title:String(d.title).trim(),category:d.category,subcategory:d.subcategory,description:String(d.description).trim(),price_from:numberFromText(d.price),city:state.user.city||'Москва',response_minutes:60,is_active:true};
    let result=await sb.from('services').insert(row).select().single();
    if(result.error&&String(result.error.message).includes('subcategory')){delete row.subcategory;result=await sb.from('services').insert(row).select().single()}
    if(result.error)throw result.error;await loadCloud();state.catalogMode='helpers';state.page='catalog';render();toast('Предложение помощи опубликовано');
  }catch(error){showFormError(form,friendlyDatabaseError(error,'Не удалось опубликовать помощь.'))}finally{setFormBusy(form,false)}
}

function chats(){
  if(!state.session){shell(`<section class="auth-gate"><h1>Чаты только между пользователями</h1><p>Войдите, чтобы увидеть свои диалоги и найти человека по ФИО.</p><button class="primary-button" onclick="showAuth('login')">Войти</button></section>`);return}
  const active=state.conversations.find(item=>item.id===state.activeConversation);
  shell(`<section class="chat-page"><aside class="chat-sidebar"><div class="chat-sidebar-head"><div><h1>Чаты</h1></div></div><form class="people-search" onsubmit="searchPeople(event)"><input name="person" value="${escapeHtml(state.chatSearch)}" placeholder="Найти человека по ФИО"><button aria-label="Найти">⌕</button></form>${state.people.length?peopleResults():conversationList()}</aside><section class="chat-dialog">${active?dialogView(active):emptyState('Выберите диалог','Здесь появится переписка с пользователем приложения.')}</section></section>`,{wide:true});
  if(active)scrollMessages();
}
function conversationList(){
  if(!state.conversations.length)return emptyState('Диалогов пока нет','Найдите пользователя по ФИО или откликнитесь на задачу.');
  return `<div class="conversation-list">${state.conversations.map(c=>{const other=conversationPartner(c),last=c.lastMessage;return `<button class="conversation-item ${state.activeConversation===c.id?'active':''}" onclick="openConversation(${arg(c.id)})">${portrait(other.avatar_url,other.name,null,'small')}<span><b>${escapeHtml(other.name||'Пользователь')}</b><small>${escapeHtml(last?.body||'Диалог создан')}</small></span><time>${last?new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit'}).format(new Date(last.created_at)):''}</time></button>`}).join('')}</div>`;
}
function peopleResults(){return `<div class="people-results"><div class="results-caption"><span>Пользователи</span><button onclick="clearPeopleSearch()">Закрыть</button></div>${state.people.map(person=>`<div class="person-result">${portrait(person.avatar_url,person.name,null,'small')}<span><b>${escapeHtml(person.name)}</b><small>${escapeHtml(person.city||'Город не указан')}</small></span><button onclick="startDirectChat(${arg(person.id)})">Написать</button></div>`).join('')}</div>`}
function conversationPartner(conversation){const uid=state.session?.user?.id;return conversation.customer_id===uid?(conversation.helper||{}):(conversation.customer||{})}
function dialogView(conversation){const other=conversationPartner(conversation);return `<header class="dialog-head">${portrait(other.avatar_url,other.name,null,'small')}<span><b>${escapeHtml(other.name||'Пользователь')}</b><small>Пользователь «Помогай»</small></span></header><div class="message-list" id="messageList">${state.messages.length?state.messages.map(message=>`<div class="message ${message.sender_id===state.session.user.id?'mine':''}"><p>${escapeHtml(message.body)}</p><time>${new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit'}).format(new Date(message.created_at))}</time></div>`).join(''):emptyState('Сообщений пока нет','Начните диалог. Сообщение увидит только второй участник.')}</div><form class="message-form" onsubmit="sendMessage(event)"><input name="body" required maxlength="4000" autocomplete="off" placeholder="Напишите сообщение"><button class="primary-button">Отправить</button></form>`}
async function searchPeople(event){event.preventDefault();const q=String(new FormData(event.currentTarget).get('person')||'').trim();state.chatSearch=q;if(q.length<2){state.people=[];render();return toast('Введите минимум 2 буквы')}const result=await sb.from('profiles').select('id,name,city,avatar_url,verified').ilike('name',`%${q.replace(/[%_,]/g,'')}%`).neq('id',state.session.user.id).limit(20);if(result.error)return toast('Не удалось выполнить поиск');state.people=result.data||[];render()}
function clearPeopleSearch(){state.chatSearch='';state.people=[];render()}
async function startDirectChat(otherUser){if(!requireAuth())return;const result=await sb.rpc('start_direct_conversation',{other_user:otherUser});if(result.error)return toast(result.error.message.includes('function')?'Прямые чаты станут доступны после обновления базы':'Не удалось создать диалог');state.people=[];state.chatSearch='';await loadConversations();await openConversation(result.data);toast('Диалог открыт')}
async function openConversation(id){state.activeConversation=id;const result=await sb.from('messages').select('id,conversation_id,sender_id,body,read_at,created_at').eq('conversation_id',id).order('created_at',{ascending:true});if(result.error)return toast('Не удалось загрузить сообщения');state.messages=result.data||[];render();subscribeToConversation(id)}
async function sendMessage(event){event.preventDefault();const form=event.currentTarget,body=String(new FormData(form).get('body')||'').trim();if(!body)return;const result=await sb.from('messages').insert({conversation_id:state.activeConversation,sender_id:state.session.user.id,body}).select().single();if(result.error)return toast('Не удалось отправить сообщение');form.reset();if(!state.messages.some(m=>m.id===result.data.id))state.messages.push(result.data);render();await loadConversations(false)}
function subscribeToConversation(id){if(!sb)return;if(state.realtimeChannel)sb.removeChannel(state.realtimeChannel);state.realtimeChannel=sb.channel(`conversation:${id}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:`conversation_id=eq.${id}`},payload=>{if(!state.messages.some(m=>m.id===payload.new.id)){state.messages.push(payload.new);render()}}).subscribe()}
function scrollMessages(){requestAnimationFrame(()=>{const element=document.querySelector('#messageList');if(element)element.scrollTop=element.scrollHeight})}

function profile(){
  if(!state.session){shell(`<section class="guest-profile"><div class="guest-avatar">П</div><span class="eyebrow">Личный профиль</span><h1>Ваше место в «Помогай»</h1><p>Управляйте публикациями, безопасностью, удостоверением личности и продвижением.</p><div class="button-row"><button class="primary-button" onclick="showAuth('login')">Войти</button><button class="secondary-button" onclick="showAuth('signup')">Создать аккаунт</button></div></section>`);return}
  const name=userName();
  shell(`<section class="profile-hero"><div class="profile-person">${portrait(state.user.avatar_url,name,null,'large')}<div><h1>${escapeHtml(name)}</h1><p>${escapeHtml(state.user.city||'Москва')}</p><div class="profile-badges">${state.user.verified?'<span class="verified-chip">Личность подтверждена</span>':'<span class="status-pill">Проверка не пройдена</span>'}</div></div></div><button class="secondary-button" onclick="editProfile()">Редактировать профиль</button></section>${profileSection('Профиль и публикации',[["ПР","Данные профиля","Фото, контакты, город, опыт и описание","editProfile()"],["МО","Мои объявления","Задачи и предложения помощи","go('create')"]])}${profileSection('Удостоверение личности',[["ID","Проверка личности",state.user.verified?'ФИО и дата рождения защищены':'Подтвердите личность перед работой с заказами',"verifyIdentity()"],["БЗ","Безопасность","Вход, пароль, приватность и жалобы","showSafety()"]])}${profileSection('Возможности профиля',[["БН","Помогай Бонусы","Получение бонусов и пакеты пополнения","showBonusShop()"],["ПР","Продвижение","Сравнить оплату рублями и бонусами","showPromotion()"]])}${profileSection('Настройки',[["НС","Настройки и вход","Уведомления, восстановление пароля, выход","showAccountSettings()"],["ПО","Поддержка","Помощь по работе сервиса","showSupport()"]])}`,{wide:true});
}
function profileSection(title,items){return `<section class="profile-section"><h2>${title}</h2><div class="profile-menu">${items.map(([mark,name,description,action])=>`<button onclick="${action}"><span class="menu-mark">${mark}</span><span><b>${name}</b><small>${description}</small></span><i>›</i></button>`).join('')}</div></section>`}
function editProfile(){
  const locked=!!state.user.verified;
  modal(`<h2>Редактирование профиля</h2><form class="form-grid" onsubmit="saveProfile(event)"><div class="avatar-editor">${portrait(state.user.avatar_url,userName(),null,'large')}<label class="secondary-button">Выбрать фото<input name="avatar" type="file" accept="image/png,image/jpeg,image/webp" hidden></label></div><label class="field full-field"><span>Полное ФИО ${locked?'· подтверждено':''}</span><input name="name" required minlength="5" maxlength="120" autocomplete="name" value="${escapeHtml(userName())}" ${locked?'readonly':''}></label><label class="field"><span>Дата рождения</span><input name="birth_date" type="date" min="1900-01-01" max="${todayIso}" value="${escapeHtml(state.user.birth_date||'')}" required ${locked?'readonly':''}></label><label class="field"><span>Город</span><input name="city" required minlength="2" maxlength="120" value="${escapeHtml(state.user.city||'Москва')}"></label><label class="field"><span>Телефон</span><input name="phone" type="tel" maxlength="30" autocomplete="tel" value="${escapeHtml(state.user.phone||'')}"></label><label class="field"><span>Опыт, лет</span><input name="experience_years" type="number" min="0" max="80" value="${escapeHtml(state.user.experience_years??'')}"></label><label class="field full-field"><span>О себе и чем можете помочь</span><textarea name="bio" maxlength="1000" rows="4">${escapeHtml(state.user.bio||'')}</textarea></label><label class="field full-field"><span>Языки</span><input name="languages" maxlength="200" value="${escapeHtml(state.user.languages||'')}" placeholder="Русский, английский"></label><div id="profileError" class="form-error full-field" hidden></div><button class="primary-button full-field">Сохранить</button></form>`);
}
function validFullName(name){return String(name||'').trim().split(/\s+/).filter(part=>part.length>=2).length>=3}
async function saveProfile(event){
  event.preventDefault();if(!state.session){showAuth('login');return}const form=event.currentTarget,d=Object.fromEntries(new FormData(form));d.name=String(d.name||'').trim().replace(/\s+/g,' ');d.city=String(d.city||'').trim();if(!validFullName(d.name))return showFormError(form,'Укажите полное ФИО: фамилию, имя и отчество.');setFormBusy(form,true);
  try{
    let avatarUrl=state.user.avatar_url||null;const file=form.querySelector('[name="avatar"]').files?.[0];if(file)avatarUrl=await uploadAvatar(file);
    const row={name:d.name,city:d.city,avatar_url:avatarUrl,bio:String(d.bio||'').trim()||null,languages:String(d.languages||'').trim()||null,experience_years:d.experience_years===''?null:Number(d.experience_years)};
    let result=await sb.from('profiles').update(row).eq('id',state.session.user.id).select().single();
    if(result.error&&String(result.error.message).match(/bio|languages|experience_years/)){const fallback={name:row.name,city:row.city,avatar_url:row.avatar_url};result=await sb.from('profiles').update(fallback).eq('id',state.session.user.id).select().single()}
    if(result.error)throw result.error;
    const privateResult=await sb.from('profile_private').upsert({id:state.session.user.id,birth_date:d.birth_date||null,phone:String(d.phone||'').trim()||null},{onConflict:'id'});
    if(privateResult.error&&!String(privateResult.error.message).includes('profile_private'))throw privateResult.error;
    await sb.auth.updateUser({data:{name:d.name,city:d.city}});await ensureProfile();closeModal();render();toast('Профиль обновлён');
  }catch(error){showFormError(form,friendlyDatabaseError(error,'Не удалось сохранить профиль.'))}finally{setFormBusy(form,false)}
}
async function uploadAvatar(file){if(file.size>5*1024*1024)throw new Error('Файл фото должен быть не больше 5 МБ.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Поддерживаются JPG, PNG и WebP.');const extension=file.type.split('/')[1].replace('jpeg','jpg'),path=`${state.session.user.id}/avatar.${extension}`,upload=await sb.storage.from('avatars').upload(path,file,{upsert:true,contentType:file.type});if(upload.error)throw upload.error;return sb.storage.from('avatars').getPublicUrl(path).data.publicUrl}
function verifyIdentity(){modal(`<h2>Удостоверение личности</h2><div class="notice">Проверка документов пока не подключена. Не загружайте паспорт или другие документы в эту версию приложения.</div><p class="muted">Перед запуском нужен отдельный KYC-провайдер, закрытое хранилище и ручная проверка спорных случаев. После подтверждения ФИО и дата рождения станут недоступны для самостоятельного изменения.</p><button class="primary-button full" onclick="closeModal()">Понятно</button>`)}
