function modal(html){closeModal(true);document.body.classList.add('modal-open');document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="modal" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true"><header class="modal-top"><button class="modal-handle" aria-label="Закрыть окно" onclick="closeModal()"></button><button class="modal-close" aria-label="Закрыть" onclick="closeModal()">×</button></header><div class="modal-content">${html}</div></section></div>`);requestAnimationFrame(()=>document.querySelector('#modal')?.classList.add('open'))}
function closeModal(immediate=false){const wrap=document.querySelector('#modal');if(!wrap)return;document.body.classList.remove('modal-open');const addressMap=state.maps.get('addressMap');if(addressMap){try{addressMap.remove()}catch{}state.maps.delete('addressMap')}if(immediate){wrap.remove();return}wrap.classList.remove('open');setTimeout(()=>wrap.remove(),180)}
function openService(id){const service=filteredServices().find(item=>item.id===id)||state.services.map(normalizedService).find(item=>item.id===id);if(!service)return;modal(`<div class="service-modal-head">${portrait(service.avatar_url,service.name,service.portrait,'large')}<div><span class="card-kicker">${escapeHtml(categoryLabel(service.category))} · ${escapeHtml(service.subcategory)}</span><h2>${escapeHtml(service.title)}</h2><p>${escapeHtml(service.name)}</p></div></div><div class="service-facts"><span><b>★ ${service.rating.toFixed(1)}</b><small>${service.reviews} отзывов</small></span><span><b>${formatMoney(service.price_from)}</b><small>Стоимость</small></span><span><b>${service.distance==null?escapeHtml(service.city):`${service.distance} км`}</b><small>Расположение</small></span></div><p class="service-description">${escapeHtml(service.description)}</p><div class="button-row"><button class="primary-button" onclick="contactService(${arg(service.owner_id)})">Написать</button><button class="secondary-button" onclick="toggleFavorite(${arg(service.id)})">${state.favorites.includes(service.id)?'Убрать из избранного':'В избранное'}</button></div><button class="text-button report-link" onclick="reportUser(${arg(service.owner_id)})">Пожаловаться</button>`)}
