async function toggleFavorite(id){if(!state.session){showAuth('login');return}if(String(id).startsWith('demo-'))return toast('Демонстрационный профиль нельзя добавить в избранное');const uid=state.session.user.id;if(state.favorites.includes(id)){const result=await sb.from('favorites').delete().eq('user_id',uid).eq('service_id',id);if(result.error)return toast('Не удалось обновить избранное');state.favorites=state.favorites.filter(item=>item!==id)}else{const result=await sb.from('favorites').insert({user_id:uid,service_id:id});if(result.error)return toast('Не удалось обновить избранное');state.favorites.push(id)}render();toast('Избранное обновлено')}
