function useMyLocation(mapId,selectable=false){
  if(!navigator.geolocation)return toast('Геолокация не поддерживается');toast('Определяем местоположение…');navigator.geolocation.getCurrentPosition(position=>{state.coords={lat:position.coords.latitude,lng:position.coords.longitude};state.locationName='Рядом со мной';savePreferences();const map=mapId&&state.maps.get(mapId);if(map){map.setView([state.coords.lat,state.coords.lng],13);if(selectable)map.fire('click',{latlng:{lat:state.coords.lat,lng:state.coords.lng}})}else{closeModal();render()}toast('Местоположение определено')},()=>toast('Разрешите доступ к геолокации в настройках браузера'),{enableHighAccuracy:true,timeout:10000,maximumAge:300000});
}
function mountDesktopNav(){const header=document.querySelector('.topbar');if(!header||header.querySelector('.desktop-nav'))return;const nav=document.createElement('nav');nav.className='desktop-nav';nav.setAttribute('aria-label','Основная навигация');nav.innerHTML=navItems.map(([id,icon,label])=>`<button class="${state.page===id?'active':''} ${id==='create'?'create-nav':''}" onclick="go('${id}')" ${state.page===id?'aria-current="page"':''}><span>${icon}</span><small>${label}</small></button>`).join('');header.querySelector('.brand')?.after(nav)}
function mountProfileFavorites(){if(state.page!=='profile'||!state.session)return;const bonus=[...document.querySelectorAll('.profile-menu>button')].find(button=>button.textContent.includes('Помогай Бонусы'));if(!bonus||bonus.parentElement.querySelector('[data-favorites-menu]'))return;const button=document.createElement('button');button.dataset.favoritesMenu='true';button.setAttribute('onclick','showFavorites()');button.innerHTML=`<span class="menu-mark">ИЗ</span><span><b>Избранные</b><small>Сохранённые специалисты, которых легко найти снова</small></span><i>›</i>`;bonus.after(button)}
