function showFavorites(){if(!state.session)return showAuth('login');const items=state.services.map(normalizedService).filter(item=>state.favorites.includes(item.id));modal(`<h2>Избранные специалисты</h2><p class="muted">Здесь сохраняются люди, к которым вы хотите вернуться.</p>${items.length?`<div class="favorite-people">${items.map(item=>`<article class="favorite-person"><button onclick="openService(${arg(item.id)})">${portrait(item.avatar_url,item.name,item.portrait,'small')}<span><b>${escapeHtml(item.name)}</b><small>${escapeHtml(item.title)}</small></span></button><button class="favorite-remove" onclick="removeFavorite(${arg(item.id)})" aria-label="Удалить из избранного">×</button></article>`).join('')}</div>`:emptyState('Избранных пока нет','Нажмите на сердечко в карточке специалиста, чтобы сохранить его здесь.')}`)}
async function removeFavorite(id){await toggleFavorite(id);showFavorites()}
let yandexMapsPromise;
function loadYandexMaps(){
  if(window.ymaps)return Promise.resolve(window.ymaps);
  const key=String((window.POMOGAY_CONFIG||{}).YANDEX_MAPS_API_KEY||'').trim();if(!key)return Promise.resolve(null);
  if(!yandexMapsPromise)yandexMapsPromise=new Promise(resolve=>{const script=document.createElement('script');script.src=`https://api-maps.yandex.ru/2.1/?apikey=${encodeURIComponent(key)}&lang=ru_RU`;script.onload=()=>window.ymaps?.ready(()=>resolve(window.ymaps));script.onerror=()=>resolve(null);document.head.append(script)});
  return yandexMapsPromise;
}
function yandexWidgetMap(element,zoom,selectable){
  const center={lat:state.coords.lat,lng:state.coords.lng};
  const draw=()=>{element.innerHTML=`<iframe class="yandex-map-frame" title="Яндекс Карта" src="https://yandex.ru/map-widget/v1/?ll=${center.lng}%2C${center.lat}&z=${zoom}&l=map" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe>${selectable?'<p class="map-fallback-note">Для точного выбора точки используйте геолокацию. Интерактивный выбор будет доступен после подключения ключа Яндекс Карт.</p>':''}`};draw();
  return {__selected:{...center},__radius:{setRadius(){}},setView(coords,nextZoom=zoom){center.lat=Number(coords[0]);center.lng=Number(coords[1]);zoom=nextZoom;this.__selected={...center};draw()},fire(type,payload){if(type==='click'&&payload?.latlng)this.__selected={lat:Number(payload.latlng.lat),lng:Number(payload.latlng.lng)}},getCenter(){return {...center}},remove(){element.replaceChildren()}};
}
async function initMap(id,items=[],selectable=false){
  const element=document.getElementById(id);if(!element)return;const existing=state.maps.get(id);if(existing)try{existing.remove()}catch{}
  const zoom=state.radius>150?6:state.radius>50?8:state.radius>15?10:12,ymaps=await loadYandexMaps();if(!document.body.contains(element))return;
  if(!ymaps){state.maps.set(id,yandexWidgetMap(element,zoom,selectable));return}
  const nativeMap=new ymaps.Map(element,{center:[state.coords.lat,state.coords.lng],zoom,controls:['zoomControl','geolocationControl']},{suppressMapOpenBlock:true});
  const radius=new ymaps.Circle([[state.coords.lat,state.coords.lng],state.radius*1000],{hintContent:'Радиус поиска'},{strokeColor:'#8f1d46',strokeWidth:2,fillColor:'#8f1d4618'});nativeMap.geoObjects.add(radius);
  nativeMap.geoObjects.add(new ymaps.Placemark([state.coords.lat,state.coords.lng],{hintContent:'Ваш центр поиска'},{preset:'islands#greenCircleDotIcon'}));
  items.forEach(item=>{const lat=Number(item.latitude),lng=Number(item.longitude);if(Number.isFinite(lat)&&Number.isFinite(lng))nativeMap.geoObjects.add(new ymaps.Placemark([lat,lng],{balloonContentHeader:escapeHtml(item.title),balloonContentBody:escapeHtml(item.subcategory||categoryLabel(item.category))},{preset:item.customer_id?'islands#blueCircleDotIcon':'islands#redCircleDotIcon'}))});
  let selected;const choose=coords=>{if(selected)nativeMap.geoObjects.remove(selected);selected=new ymaps.Placemark(coords,{}, {preset:'islands#redCircleDotIcon'});nativeMap.geoObjects.add(selected);adapter.__selected={lat:Number(coords[0]),lng:Number(coords[1])};nativeMap.panTo(coords)};
  const adapter={__selected:null,__radius:{setRadius(meters){radius.geometry.setRadius(meters)}},setView(coords,nextZoom=zoom){nativeMap.setCenter(coords,nextZoom)},fire(type,payload){if(type==='click'&&payload?.latlng)choose([payload.latlng.lat,payload.latlng.lng])},getCenter(){const point=nativeMap.getCenter();return{lat:Number(point[0]),lng:Number(point[1])}},remove(){nativeMap.destroy()}};
  if(selectable){nativeMap.events.add('click',event=>choose(event.get('coords')));choose([state.coords.lat,state.coords.lng])}state.maps.set(id,adapter);
}
function updateMapRadius(){for(const map of state.maps.values())if(map.__radius)map.__radius.setRadius(state.radius*1000)}

const cfg=window.POMOGAY_CONFIG||{};
const sb=window.supabase&&cfg.SUPABASE_URL&&cfg.SUPABASE_ANON_KEY?window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_ANON_KEY,{auth:{flowType:'pkce',detectSessionInUrl:false,persistSession:true,autoRefreshToken:true}}):null;
function requireAuth(){if(!state.session){showAuth('login');toast('Сначала войдите или зарегистрируйтесь');return false}if(!validFullName(state.user.name)||!state.user.birth_date){editProfile();toast('Завершите профиль: укажите полное ФИО и дату рождения');return false}return true}
function isNativeApp(){return !!(window.Capacitor&&window.Capacitor.isNativePlatform&&window.Capacitor.isNativePlatform())}
function getAuthRedirectUrl(){return isNativeApp()?'pomogay://auth-callback':`${location.origin}${location.pathname}`}
let pendingSignup=null;
function showAuth(mode='login'){
  if(mode==='signup'){showSignupIdentity();return}
  modal(`<div class="auth-panel"><h2>Вход</h2><form class="auth-login-form" onsubmit="authSubmit(event)"><label class="auth-input"><span class="sr-only">Телефон или почта</span><input name="identity" required autocomplete="username" inputmode="email" placeholder="Телефон или почта"></label><label class="auth-input"><span class="sr-only">Пароль</span><input name="password" type="password" required autocomplete="current-password" placeholder="Пароль"></label><div class="auth-options"><label class="remember-password"><input name="remember" type="checkbox" checked><span>Запомнить пароль</span></label><button class="text-button" type="button" onclick="showPasswordReset()">Забыли пароль?</button></div><div id="authError" class="form-error" hidden></div><button class="primary-button auth-login-submit">Войти</button></form><section class="auth-alternatives"><p>Или продолжить через</p><div class="auth-provider-row"><button type="button" onclick="externalAuth('yandex')" aria-label="Продолжить через Яндекс"><span class="auth-provider yandex">Я</span><small>Яндекс</small></button><button type="button" onclick="externalAuth('gosuslugi')" aria-label="Продолжить через Госуслуги"><span class="auth-provider gosuslugi"><i></i></span><small>Госуслуги</small></button></div><p class="auth-signup-question">Нет аккаунта в Помогай?</p><button class="secondary-button auth-register-button" onclick="showAuth('signup')">Зарегистрироваться</button></section></div>`);
}
function showSignupIdentity(){
  pendingSignup=null;
  modal(`<div class="auth-panel signup-step"><button class="auth-step-back" type="button" onclick="showAuth('login')" aria-label="Вернуться ко входу">←</button><span class="auth-step-count">Шаг 1 из 2</span><h2>Регистрация</h2><p class="muted">Введите телефон или email. На него придёт подтверждение аккаунта.</p><form class="signup-step-form" onsubmit="continueSignupIdentity(event)"><label class="auth-input"><span class="sr-only">Телефон или email</span><input name="identity" required autocomplete="username" inputmode="email" placeholder="Телефон или email" autofocus></label><div class="form-error" hidden></div><button class="primary-button full" type="submit">Продолжить</button></form><div class="divider signup-divider"><span>или продолжить через</span></div><div class="auth-provider-row signup-providers"><button type="button" onclick="externalAuth('yandex')" aria-label="Зарегистрироваться через Яндекс"><span class="auth-provider yandex">Я</span><small>Яндекс</small></button><button type="button" onclick="externalAuth('gosuslugi')" aria-label="Зарегистрироваться через Госуслуги"><span class="auth-provider gosuslugi"><i></i></span><small>Госуслуги</small></button></div><p class="auth-signup-question">Уже есть аккаунт?</p><button class="text-button auth-back-login" onclick="showAuth('login')">Войти</button></div>`);
}
function credentialsForIdentity(identity,password){
  const value=String(identity||'').trim();
  if(value.includes('@'))return {email:value.toLowerCase(),password};
  let phone=value.replace(/[^\d+]/g,'');
  if(phone.startsWith('8')&&phone.replace(/\D/g,'').length===11)phone=`+7${phone.slice(1)}`;
  else if(!phone.startsWith('+')&&phone.replace(/\D/g,'').length===10)phone=`+7${phone}`;
  else if(!phone.startsWith('+'))phone=`+${phone}`;
  return {phone,password};
}
function continueSignupIdentity(event){
  event.preventDefault();const form=event.currentTarget,value=String(new FormData(form).get('identity')||'').trim(),credentials=credentialsForIdentity(value,'');
  if(credentials.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(credentials.email))return showFormError(form,'Введите корректный email.');
  if(credentials.phone){const digits=credentials.phone.replace(/\D/g,'');if(digits.length<10||digits.length>15)return showFormError(form,'Введите корректный номер телефона.');}
  pendingSignup={method:credentials.email?'email':'phone',credential:credentials.email||credentials.phone};showSignupPassword();
}
function showSignupPassword(){
  if(!pendingSignup){showSignupIdentity();return}
  modal(`<div class="auth-panel signup-step"><button class="auth-step-back" type="button" onclick="showSignupIdentity()" aria-label="Вернуться к телефону или email">←</button><span class="auth-step-count">Шаг 2 из 2</span><h2>Придумайте пароль</h2><p class="signup-identity-preview">${escapeHtml(pendingSignup.credential)}</p><form class="signup-step-form" onsubmit="submitSignupPassword(event)"><label class="auth-input"><span class="sr-only">Пароль</span><input name="password" type="password" minlength="8" required autocomplete="new-password" placeholder="Пароль" oninput="updatePasswordRules(this)"></label><ul class="password-rules" aria-live="polite"><li data-rule="length">Минимум 8 символов</li><li data-rule="letter">Хотя бы одна буква</li><li data-rule="number">Хотя бы одна цифра</li></ul><div class="form-error" hidden></div><button class="primary-button full signup-password-submit" type="submit" disabled>Продолжить</button></form></div>`);
}
function passwordIsValid(value){return String(value).length>=8&&/[A-Za-zА-Яа-яЁё]/.test(value)&&/\d/.test(value)}
function updatePasswordRules(input){
  const form=input.form,value=input.value,rules={length:value.length>=8,letter:/[A-Za-zА-Яа-яЁё]/.test(value),number:/\d/.test(value)};
  Object.entries(rules).forEach(([rule,valid])=>form.querySelector(`[data-rule="${rule}"]`)?.classList.toggle('valid',valid));form.querySelector('.signup-password-submit').disabled=!Object.values(rules).every(Boolean);
}
async function submitSignupPassword(event){
  event.preventDefault();const form=event.currentTarget,password=String(new FormData(form).get('password')||'');if(!pendingSignup)return showSignupIdentity();if(!passwordIsValid(password))return showFormError(form,'Пароль должен содержать минимум 8 символов, буквы и цифры.');if(!sb)return showFormError(form,'Не удалось подключиться к сервису аккаунтов.');setFormBusy(form,true);
  try{
    const credentials=pendingSignup.method==='email'?{email:pendingSignup.credential,password}:{phone:pendingSignup.credential,password},result=await sb.auth.signUp({...credentials,options:{emailRedirectTo:getAuthRedirectUrl()}});if(result.error)throw result.error;
    if(pendingSignup.method==='phone'){showPhoneVerification(pendingSignup.credential);return}
    if(result.data.session)await sb.auth.signOut();showEmailVerification(pendingSignup.credential);
  }catch(error){showFormError(form,friendlyAuthError(error))}finally{setFormBusy(form,false)}
}
async function authSubmit(event){
  event.preventDefault();if(!sb)return showFormError(event.currentTarget,'Не удалось подключиться к сервису аккаунтов.');const form=event.currentTarget,d=Object.fromEntries(new FormData(form)),credentials=credentialsForIdentity(d.identity,d.password);setFormBusy(form,true);
  try{const result=await sb.auth.signInWithPassword(credentials);if(result.error)throw result.error;state.session=result.data.session;await ensureProfile();closeModal();await loadCloud();render();toast('Вы вошли')}catch(error){showFormError(form,friendlyAuthError(error))}finally{setFormBusy(form,false)}
}
function showEmailVerification(email){modal(`<div class="auth-panel verification-step"><span class="verification-mark">✓</span><h2>Подтвердите email</h2><p>Мы отправили ссылку на <b>${escapeHtml(email)}</b>. Перейдите по ней, чтобы завершить регистрацию.</p><button class="primary-button full" onclick="showAuth('login')">Перейти ко входу</button></div>`)}
function showPhoneVerification(phone){modal(`<h2>Подтверждение телефона</h2><p class="muted">Введите код из SMS, отправленный на ${escapeHtml(phone)}.</p><form class="form-grid" onsubmit="verifyPhoneOtp(event,${arg(phone)})"><label class="field full-field"><span>Код из SMS</span><input name="token" inputmode="numeric" autocomplete="one-time-code" minlength="6" maxlength="8" required placeholder="000000"></label><div class="form-error full-field" hidden></div><button class="primary-button full-field">Подтвердить</button></form>`)}
async function verifyPhoneOtp(event,phone){event.preventDefault();const form=event.currentTarget,token=String(new FormData(form).get('token')||'').replace(/\D/g,'');setFormBusy(form,true);const result=await sb.auth.verifyOtp({phone,token,type:'sms'});setFormBusy(form,false);if(result.error)return showFormError(form,'Неверный или просроченный код.');state.session=result.data.session;await ensureProfile();closeModal();await loadCloud();render();toast('Телефон подтверждён')}
function externalAuth(provider){const label=provider==='yandex'?'Яндекс':'Госуслуги',url=provider==='yandex'?cfg.YANDEX_AUTH_URL:cfg.GOSUSLUGI_AUTH_URL;if(!url)return toast(`Вход через ${label} станет доступен после подключения провайдера`);location.assign(url)}
async function oauthSignIn(provider){if(!sb)return toast('Сервис входа недоступен');const result=await sb.auth.signInWithOAuth({provider,options:{redirectTo:getAuthRedirectUrl(),skipBrowserRedirect:isNativeApp()}});if(result.error)toast('Этот способ входа пока не включён администратором');else if(isNativeApp()&&result.data.url)location.href=result.data.url}
function showPasswordReset(){modal(`<h2>Восстановление пароля</h2><p class="muted">Отправим одноразовую безопасную ссылку на email аккаунта.</p><form class="form-grid" onsubmit="requestPasswordReset(event)"><label class="field full-field"><span>Email</span><input name="email" type="email" required autocomplete="email" inputmode="email" value="${escapeHtml(state.session?.user?.email||'')}" placeholder="name@example.com"></label><div class="form-error full-field" hidden></div><button class="primary-button full-field">Отправить ссылку</button></form>`)}
async function requestPasswordReset(event){event.preventDefault();if(!sb)return;const form=event.currentTarget,email=String(new FormData(form).get('email')||'').trim().toLowerCase();setFormBusy(form,true);const result=await sb.auth.resetPasswordForEmail(email,{redirectTo:getAuthRedirectUrl()});setFormBusy(form,false);if(result.error)return showFormError(form,'Не удалось отправить письмо. Проверьте адрес и попробуйте снова.');closeModal();toast('Ссылка для сброса пароля отправлена на email')}
function showNewPassword(){modal(`<h2>Новый пароль</h2><form class="form-grid" onsubmit="updatePassword(event)"><label class="field full-field"><span>Новый пароль</span><input name="password" type="password" minlength="12" required autocomplete="new-password" placeholder="Не менее 12 символов"></label><div class="form-error full-field" hidden></div><button class="primary-button full-field">Сохранить пароль</button></form>`)}
async function updatePassword(event){event.preventDefault();const form=event.currentTarget,password=new FormData(form).get('password'),result=await sb.auth.updateUser({password});if(result.error)return showFormError(form,'Не удалось изменить пароль.');closeModal();toast('Пароль изменён')}
function friendlyAuthError(error){const text=String(error?.message||'');if(text.includes('Invalid login credentials'))return'Неверный email или пароль.';if(text.includes('already registered'))return'Такой email уже зарегистрирован.';if(text.includes('Email not confirmed'))return'Сначала подтвердите email по ссылке из письма.';return'Не удалось выполнить вход. Попробуйте ещё раз.'}
function friendlyDatabaseError(error,fallback){const text=String(error?.message||'');if(text.includes('5 МБ')||text.includes('JPG'))return text;if(text.includes('verified identity'))return'Подтверждённые ФИО и дату рождения можно изменить только через поддержку.';return fallback}
function clearPrivateSessionState(){state.user={name:'',city:'Москва',verified:false};state.tasks=[];state.conversations=[];state.messages=[];state.people=[];state.favorites=[];state.activeConversation=null}
async function signOut(){try{if(sb)await sb.auth.signOut()}finally{closeModal();state.session=null;clearPrivateSessionState();state.page='home';render();toast('Вы вышли')}}

window.handleAuthDeepLink=async function(url){
  if(!sb||!url)return false;
  try{
    const parsed=new URL(url),trusted=isNativeApp()?parsed.protocol==='pomogay:'&&parsed.hostname==='auth-callback':parsed.origin===location.origin;if(!trusted)throw new Error('Untrusted auth callback URL');const query=parsed.searchParams,hash=new URLSearchParams((parsed.hash||'').replace(/^#/,'')),errorDescription=query.get('error_description')||hash.get('error_description');if(errorDescription)throw new Error(decodeURIComponent(errorDescription));const code=query.get('code');if(code){const result=await sb.auth.exchangeCodeForSession(code);if(result.error)throw result.error;state.session=result.data.session;await ensureProfile();closeModal();render();return true}const access_token=hash.get('access_token')||query.get('access_token'),refresh_token=hash.get('refresh_token')||query.get('refresh_token');if(access_token&&refresh_token){const result=await sb.auth.setSession({access_token,refresh_token});if(result.error)throw result.error;state.session=result.data.session;await ensureProfile();closeModal();render();return true}return false;
  }catch(error){console.warn('Auth callback error',error);toast('Не удалось завершить вход. Попробуйте ещё раз.');return false}
};

async function ensureProfile(){
  if(!sb||!state.session)return;const user=state.session.user,meta=user.user_metadata||{};let result=await sb.from('profiles').select('*').eq('id',user.id).maybeSingle();if(result.error)console.warn(result.error);let data=result.data;if(!data){const fallback={id:user.id,name:meta.name||user.email?.split('@')[0]||'Пользователь',city:meta.city||'Москва',avatar_url:meta.avatar_url||null},created=await sb.from('profiles').insert(fallback).select().single();if(!created.error)data=created.data}
  if(data){
    const privateResult=await sb.from('profile_private').select('birth_date,phone').eq('id',user.id).maybeSingle();
    const privateData=privateResult.error?{}:(privateResult.data||{});
    state.user={name:data.name||meta.name||'Пользователь',city:data.city||meta.city||'Москва',verified:!!data.verified,avatar_url:data.avatar_url||meta.avatar_url||null,birth_date:privateData.birth_date||meta.birth_date||'',phone:privateData.phone||'',bio:data.bio||'',languages:data.languages||'',experience_years:data.experience_years??''};
  }
}
function taskFromRow(row){return{...row,category:categoryId(row.category),subcategory:row.subcategory||''}}
async function loadCloud(){
  if(!sb)return;
  try{
    const services=await sb.from('services').select('*,profiles(name,rating,verified,avatar_url)').eq('is_active',true).order('created_at',{ascending:false});if(!services.error)state.services=[...(services.data||[]),...seedServices];
    const tasks=await sb.from('tasks').select('*').eq('status','open').order('created_at',{ascending:false});if(!tasks.error)state.tasks=(tasks.data||[]).map(taskFromRow);
    if(state.session){const favorites=await sb.from('favorites').select('service_id').eq('user_id',state.session.user.id);if(!favorites.error)state.favorites=(favorites.data||[]).map(item=>item.service_id);await loadConversations(false)}state.cloudReady=true;
  }catch(error){console.warn('Cloud load',error)}
}
async function loadConversations(shouldRender=true){
  if(!sb||!state.session)return;const uid=state.session.user.id,result=await sb.from('conversations').select('id,task_id,customer_id,helper_id,created_at,customer:profiles!conversations_customer_id_fkey(id,name,avatar_url),helper:profiles!conversations_helper_id_fkey(id,name,avatar_url),messages(id,body,sender_id,created_at,read_at)').or(`customer_id.eq.${uid},helper_id.eq.${uid}`).order('created_at',{ascending:false});if(result.error){console.warn(result.error);return}state.conversations=(result.data||[]).map(item=>({...item,lastMessage:[...(item.messages||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0]||null})).sort((a,b)=>new Date(b.lastMessage?.created_at||b.created_at)-new Date(a.lastMessage?.created_at||a.created_at));if(shouldRender)render()}
function showLegal(kind){modal(`<h2>${kind==='privacy'?'Конфиденциальность':'Правила общения'}</h2><p class="muted">${kind==='privacy'?'Публично показываются только данные, нужные для выбора специалиста. Точный адрес задачи не должен отображаться до согласования с исполнителем.':'Не переводите предоплату незнакомым людям, не отправляйте документы в чате и фиксируйте условия задачи до начала работы.'}</p><button class="primary-button full" onclick="closeModal()">Понятно</button>`)}
function installHelp(){toast('Установите приложение через меню браузера «На экран Домой»')}
function render(){({home,catalog,create,chats,profile}[state.page]||home)()}

async function initApp(){
  Object.assign(window,{state,go,render,selectIntent,continueIntent,applyCategory,openCategory,showAllCategories,chooseSubcategory,setCatalogMode,setCategory,setSubcategory,setView,searchCatalog,showFilters,refreshFilterSubcategories,applyFilters,previewRadius,commitRadius,setCreateMode,updateCreateSubcategories,openAddressPicker,confirmAddress,publishTask,publishService,searchPeople,clearPeopleSearch,startDirectChat,openConversation,sendMessage,editProfile,saveProfile,verifyIdentity,showSafety,showAccountSettings,showSupport,showBonusShop,showPromotion,paymentUnavailable,openService,contactService,toggleFavorite,respondToTask,reportUser,showLocationMenu,chooseCity,setCity,useMyLocation,closeModal,showAuth,showSignupIdentity,continueSignupIdentity,showSignupPassword,updatePasswordRules,submitSignupPassword,authSubmit,oauthSignIn,requestPasswordReset,updatePassword,signOut,showLegal,installHelp});
  render();if(!sb){toast('Не удалось подключиться к Supabase');return}const session=await sb.auth.getSession();state.session=session.data.session;if(location.search.includes('code=')||location.hash.includes('access_token=')){await window.handleAuthDeepLink(location.href);history.replaceState({},document.title,location.pathname)}await ensureProfile();await loadCloud();render();sb.auth.onAuthStateChange(async(event,sessionValue)=>{state.session=sessionValue;if(event==='PASSWORD_RECOVERY')showNewPassword();if(!sessionValue)clearPrivateSessionState();await ensureProfile();await loadCloud();render()});if('serviceWorker'in navigator&&!isNativeApp())navigator.serviceWorker.register('sw.js')
}
initApp();
